/**
 * base-sizes.ts — reconcile a unit's representative `base_size_mm` against the
 * GW MFM dump's per-datasheet base-size label (the `base-sizes` subcommand).
 *
 * The dump exposes `datasheet.localisations.en.baseSize` as a display string.
 * This pass parses only the CONFIDENT, unambiguous forms — a single round
 * diameter (`40mm`, `28.5mm`) or a single oval (`120 x 92mm Oval Base`,
 * `75x42mm`) — and reconciles them onto the matched repo unit. Everything else is
 * deliberately skipped and the authored value is kept:
 *   - categories the GW guide gives without mm (`Hull`, `Large/Small Flying
 *     Base`, `Unique`) — no dimensions to import;
 *   - per-model / multi strings (comma-, colon-, or newline-separated, e.g.
 *     `Sword Brother: 40mm` / `Other models: 32mm`) — the representative base
 *     can't be picked from the string alone, so these stay in per-model
 *     unit-composition authoring;
 *   - ambiguous single-number "ovals" (`105mm oval`, `150mm Oval Base`).
 *
 * The MFM base size IS an authoritative source, so a parsed value is written
 * with no `draft` flag. Reconcile precedence per matched unit:
 *   - no authored value            → FILL from the dump.
 *   - authored == dump, was draft  → DE-DRAFT (drop the provisional flag).
 *   - authored == dump, not draft  → confirm (no change).
 *   - authored != dump, was draft  → CORRECT (replace the guess with the dump).
 *   - authored != dump, not draft  → REVIEW (surfaced, never overwritten — a
 *                                    hand-authored value the dump contradicts).
 *
 * Datasheet→repo-unit matching reuses {@link forEachDirDatasheet} (home faction
 * first, shared-roster fallback), so it can't drift from the wargear reconcile.
 * Mutations are applied in BOTH dry-run and write modes and routed through
 * {@link applyWrites}, which validates the projected dataset and only persists on
 * --write.
 */
import * as fs from "fs";
import * as path from "path";
import { MfmDump, type DatasheetRow } from "./loader.js";
import { CORE_DIR, readJsonArray } from "./repo-files.js";
import { forEachDirDatasheet } from "./wargear.js";
import type { StagedWrite } from "./apply.js";

export interface BaseSize {
  shape: "round" | "oval" | "flying-base" | "hull" | "unique";
  diameter?: number;
  width?: number;
  length?: number;
  size?: "small" | "large";
  draft?: boolean;
}

/**
 * Parse a dump `baseSize` label to a repo base-size object — confident cases
 * only. Returns null for categories, per-model/multi strings, and ambiguous
 * single-number ovals (the caller keeps the authored value for those).
 */
export function parseBaseSize(raw: string | null | undefined): BaseSize | null {
  if (raw == null) return null;
  const s = String(raw).trim();
  // Reject per-model / multi strings and empties up front.
  if (s === "" || /[,:\n]/.test(s)) return null;
  let m = s.match(/^(\d+(?:\.\d+)?)\s*mm$/i);
  if (m) return { shape: "round", diameter: parseFloat(m[1]) };
  m = s.match(/^(\d+(?:\.\d+)?)\s*x\s*(\d+(?:\.\d+)?)\s*mm(?:\s+oval\s+base)?$/i);
  if (m) return { shape: "oval", width: parseFloat(m[1]), length: parseFloat(m[2]) };
  return null;
}

/** Dimensional equality (shape + mm), ignoring the draft flag. */
export function baseSizeEqual(a: BaseSize | undefined, b: BaseSize): boolean {
  if (!a || a.shape !== b.shape) return false;
  if (b.shape === "round") return a.diameter === b.diameter;
  if (b.shape === "oval") return a.width === b.width && a.length === b.length;
  return false; // only round/oval are dump-derived
}

const baseSizeRaw = (ds: DatasheetRow): string | undefined =>
  (ds.localisations?.en as { baseSize?: string } | undefined)?.baseSize;

/** dir → unitId → dump-derived base size (confident round/oval only). */
export function buildBaseSizeCanon(dump: MfmDump): Map<string, Map<string, BaseSize>> {
  const out = new Map<string, Map<string, BaseSize>>();
  forEachDirDatasheet(dump, ({ dir, ds, unitId }) => {
    const parsed = parseBaseSize(baseSizeRaw(ds));
    if (!parsed) return;
    (out.get(dir) ?? out.set(dir, new Map<string, BaseSize>()).get(dir)!).set(unitId, parsed);
  });
  return out;
}

interface UnitRecord {
  id: string;
  base_size_mm?: BaseSize;
  [k: string]: unknown;
}

export interface BaseSizeReport {
  filled: { dir: string; id: string }[];
  dedrafted: { dir: string; id: string }[];
  corrected: { dir: string; id: string; from: string; to: string }[];
  review: { dir: string; id: string; authored: string; dump: string }[];
  confirmed: number;
  staged: StagedWrite[];
}

const fmt = (b: BaseSize): string =>
  b.shape === "round" ? `round ${b.diameter}` : b.shape === "oval" ? `oval ${b.width}x${b.length}` : b.shape;

export function runBaseSizes(dump: MfmDump): BaseSizeReport {
  const canon = buildBaseSizeCanon(dump);
  const report: BaseSizeReport = {
    filled: [],
    dedrafted: [],
    corrected: [],
    review: [],
    confirmed: 0,
    staged: [],
  };

  for (const [dir, unitMap] of canon) {
    const upath = path.join(CORE_DIR, dir, "units.json");
    if (!fs.existsSync(upath)) continue;
    const units = readJsonArray<UnitRecord>(upath);
    const byId = new Map(units.map((u) => [u.id, u]));
    let dirty = false;

    for (const [id, parsed] of unitMap) {
      const u = byId.get(id);
      if (!u) continue;
      const cur = u.base_size_mm;
      if (!cur) {
        u.base_size_mm = { ...parsed };
        report.filled.push({ dir, id });
        dirty = true;
      } else if (baseSizeEqual(cur, parsed)) {
        if (cur.draft) {
          delete cur.draft; // the dump confirms a provisional value
          report.dedrafted.push({ dir, id });
          dirty = true;
        } else {
          report.confirmed++;
        }
      } else if (cur.draft) {
        report.corrected.push({ dir, id, from: fmt(cur), to: fmt(parsed) });
        u.base_size_mm = { ...parsed };
        dirty = true;
      } else {
        // hand-authored (non-draft) disagreement — surface, never overwrite.
        report.review.push({ dir, id, authored: fmt(cur), dump: fmt(parsed) });
      }
    }

    if (dirty) report.staged.push({ path: upath, value: units });
  }
  return report;
}

export function buildBaseSizeReport(report: BaseSizeReport, write: boolean): string {
  const L: string[] = [];
  L.push(`# MFM base sizes — ${write ? "APPLIED" : "DRY RUN"}`);
  L.push("");
  L.push("Reconciles unit `base_size_mm` from the dump's datasheet baseSize label,");
  L.push("confident round/oval strings only (Hull/Flying/Unique, per-model, and");
  L.push("ambiguous ovals are skipped — authored values kept). A dump value is");
  L.push("authoritative (draft:false); non-draft authored disagreements are surfaced,");
  L.push("never overwritten.");
  L.push("");
  L.push("| Metric | Count |");
  L.push("|---|--:|");
  L.push(`| Filled (was empty) | ${report.filled.length} |`);
  L.push(`| De-drafted (dump confirmed a guess) | ${report.dedrafted.length} |`);
  L.push(`| Corrected (dump fixed a draft) | ${report.corrected.length} |`);
  L.push(`| Confirmed (already matched) | ${report.confirmed} |`);
  L.push(`| Review (authored ≠ dump, kept) | ${report.review.length} |`);
  L.push("");
  if (report.corrected.length) {
    L.push("## Corrected drafts (dump-authoritative)", "");
    report.corrected.forEach((c) => L.push(`- ${c.dir}/${c.id}: ${c.from} → ${c.to}`));
    L.push("");
  }
  if (report.review.length) {
    L.push("## Review — authored value the dump contradicts (NOT changed)", "");
    report.review.forEach((r) => L.push(`- ${r.dir}/${r.id}: authored ${r.authored} vs dump ${r.dump}`));
    L.push("");
  }
  return L.join("\n") + "\n";
}
